-- seed_oli_gardan_samping_cvt.sql — generated dari 3 file xlsx
--   database_oli_gardan.xlsx: 12 baris
--   database_oli_samping_2T.xlsx: 10 baris
--   database_CVT.xlsx: 16 baris
-- Cara pakai: Supabase Dashboard > SQL Editor > New Query > paste file ini > Run
-- Idempotent: ON CONFLICT(slug) DO UPDATE, aman di-run ulang

on conflict (slug) do update set brand = excluded.brand, name = excluded.name, harga_min = excluded.harga_min, harga_max = excluded.harga_max, satuan = excluded.satuan, specs = excluded.specs, keunggulan = excluded.keunggulan, cocok_motor = excluded.cocok_motor, interval_km = excluded.interval_km, deskripsi = excluded.deskripsi;

select category, count(*) from parts where category in ('oli-gardan','oli-samping','cvt') group by category;
